NSString *const kAdvancedSettingDescription = @"kAdvancedSettingDescription";
NSString *const kAdvancedSettingSetter = @"kAdvancedSettingSetter";
NSString *const kAdvancedSettingGetter = @"kAdvancedSettingGetter";
