DEFINE_BOOL(focusReportingEnabled, YES, SECTION_TERMINAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.focusReportingEnabled", nil, [NSBundle mainBundle], @"Apps may turn on Focus Reporting.\nFocus reporting causes iTerm2 to send an escape sequence when a session gains or loses focus. It can cause problems when an ssh session dies unexpectedly because it gets left on, so some users prefer to disable it.", @"Advanced setting: focusReportingEnabled"));
DEFINE_BOOL(useColorfgbgFallback, YES, SECTION_TERMINAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.useColorfgbgFallback", nil, [NSBundle mainBundle], @"Use fallback for COLORFGBG if no exact match found?\nThe COLORFGBG variable indicates the ANSI colors that match the foreground and background colors. If no colors match and this setting is enabled, then the variable will be set to 15;0 to indicate a dark background or 0;15 to indicate a light background.", @"Advanced setting: useColorfgbgFallback"));
DEFINE_BOOL(zeroWidthSpaceAdvancesCursor, YES, SECTION_TERMINAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.zeroWidthSpaceAdvancesCursor", nil, [NSBundle mainBundle], @"Zero-Width Space (U+200B) advances cursor?\nWhile a zero-width space should not advance the cursor per the Unicode spec, both Terminal.app and Konsole do this, and Weechat depends on it. You must restart iTerm2 after changing this setting.", @"Advanced setting: zeroWidthSpaceAdvancesCursor"));
DEFINE_BOOL(stripZeroWidthFormatCharactersOnPaste, NO, SECTION_TERMINAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.stripZeroWidthFormatCharactersOnPaste", nil, [NSBundle mainBundle], @"Strip zero-width bidi/format characters when pasting?\nCharacters like the Zero-Width Non-Joiner (U+200C, the Persian half-space), ZWJ, LRM, and RLM are invisible but macOS classifies them as control characters, so line editors like zsh render them as a visible <200c> at the prompt. Turn this on to remove them from pasted text so the command line stays clean. Off by default because these characters are meaningful; enabling this changes the pasted text.", @"Advanced setting: stripZeroWidthFormatCharactersOnPaste"));
DEFINE_BOOL(fullHeightCursor, NO, SECTION_TERMINAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.fullHeightCursor", nil, [NSBundle mainBundle], @"Cursor occupies line spacing area.\nIf lines have more than 100% vertical spacing and this setting is enabled the bottom of the cursor will be aligned to the bottom of the spacing area.", @"Advanced setting: fullHeightCursor"));
