DEFINE_BOOL(preventSleepOnBatteryToo, NO, SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.preventSleepOnBatteryToo", nil, [NSBundle mainBundle], @"Prevent system idle sleep on battery too, for profiles with “Prevent sleep” enabled?\nBy default the “Prevent sleep” profile setting only prevents idle sleep while connected to power. Enable this to also prevent idle sleep on battery.", @"Advanced setting: preventSleepOnBatteryToo"));
