DEFINE_BOOL(jiggleTTYSizeOnClearBuffer, NO, SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.jiggleTTYSizeOnClearBuffer", nil, [NSBundle mainBundle], @"Redraw the screen after the Clear Buffer menu item is selected.\nWhen enabled, the TTY size is briefly changed after clearing the buffer to cause the shell or current app to redraw.", @"Advanced setting: jiggleTTYSizeOnClearBuffer"));
DEFINE_BOOL(saveScrollBufferWhenClearing, YES, SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.saveScrollBufferWhenClearing", nil, [NSBundle mainBundle], @"Save scroll buffer when clearing screen.\nWhen enabled, saves the current screen into scroll back buffer instead of clearing it.", @"Advanced setting: saveScrollBufferWhenClearing"));
DEFINE_BOOL(saveScrollbackWhenCursorMovesAbovePrompt, YES, SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.saveScrollbackWhenCursorMovesAbovePrompt", nil, [NSBundle mainBundle], @"Save the screen to scrollback when an app moves the cursor above the prompt.\nSome full-screen programs that don’t use the alternate screen buffer repaint by moving the cursor to the top of the screen and overwriting whatever was already there, destroying content you can still see. When enabled, iTerm2 first scrolls the visible screen into history so that content isn’t lost. Requires shell integration.", @"Advanced setting: saveScrollbackWhenCursorMovesAbovePrompt"));
DEFINE_BOOL(indicateBellsInDockBadgeLabel, YES, SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.indicateBellsInDockBadgeLabel", nil, [NSBundle mainBundle], @"Indicate the number of bells rung while the app is inactive in the dock icon’s badge label", @"Advanced setting: indicateBellsInDockBadgeLabel"));
DEFINE_BOOL(showSuiteNameInDockIcon, YES, SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.showSuiteNameInDockIcon", nil, [NSBundle mainBundle], @"Overlay the suite name on the dock icon when launched with -suite.\nWhen you run an isolated instance with the -suite argument, its name is drawn across the lower third of the dock icon so you can tell instances apart.", @"Advanced setting: showSuiteNameInDockIcon"));
DEFINE_STRING(downloadsDirectory, @"", SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.downloadsDirectory", nil, [NSBundle mainBundle], @"Downloads folder.\nIf set, downloaded files go to this location instead of the user’s $HOME/Downloads folder.", @"Advanced setting: downloadsDirectory"));
