DEFINE_BOOL(hideStuckTooltips, YES, SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.hideStuckTooltips", nil, [NSBundle mainBundle], @"Hide stuck tooltips.\nWhen you hide iTerm2 using a hotkey while a tooltip is fading out it gets stuck because of an OS bug. Work around it with a nasty hack by enabling this feature.", @"Advanced setting: hideStuckTooltips"))
DEFINE_BOOL(openFileOverridesSendText, YES, SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.openFileOverridesSendText", nil, [NSBundle mainBundle], @"Should opening a script with iTerm2 disable the default profile's “Send Text at Start” setting?\nIf you use “open iTerm2 file.command” or drag a script onto iTerm2's icon and this setting is enabled then the script will be executed in lieu of the profile's “Send Text at Start” setting. If this setting is off then both will be executed.", @"Advanced setting: openFileOverridesSendText"));
DEFINE_BOOL(statusBarIcon, YES, SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.statusBarIcon", nil, [NSBundle mainBundle], @"Add status bar icon when excluded from dock?\nWhen you turn on “Exclude from Dock and ⌘-Tab Application Switcher” a status bar icon is added to the menu bar so you can switch the setting back off. Disable this to remove the status bar icon. Doing so makes it very hard to get to Settings. You must restart iTerm2 after changing this setting.", @"Advanced setting: statusBarIcon"));
DEFINE_FLOAT(statusBarHeight, 21, SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.statusBarHeight", nil, [NSBundle mainBundle], @"Height of the status bar in points.\nThis will also affect the height of per-pane title bars becuase the status bar may be embedded in it. You must restart iTerm2 after changing this setting for it to take effect.", @"Advanced setting: statusBarHeight"));
