DEFINE_FLOAT(timeToWaitForEmojiPanel, 1, SECTION_GENERAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.timeToWaitForEmojiPanel", nil, [NSBundle mainBundle], @"How long to wait for the emoji panel to open in seconds?\nFloating hotkey windows adjust their level when the emoji panel is open. If it’s really slow you might need to increase this value to prevent it from appearing beneath a floating hotkey window.", @"Advanced setting: timeToWaitForEmojiPanel"));
