DEFINE_FLOAT(activeUpdateCadence, 60.0, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.activeUpdateCadence", nil, [NSBundle mainBundle], @"Maximum frame rate (FPS) when adaptive framerate is disabled.\nNote: this is doubled on ARM Macs for displays that support at least 120hz. Modifications to this setting will not affect existing sessions.", @"Advanced setting: activeUpdateCadence"));
DEFINE_INT(adaptiveFrameRateThroughputThreshold, 10000, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.adaptiveFrameRateThroughputThreshold", nil, [NSBundle mainBundle], @"Throughput threshold for adaptive frame rate.\nIf more than this many bytes per second are received, use the lower frame rate of 30 fps.", @"Advanced setting: adaptiveFrameRateThroughputThreshold"));
DEFINE_FLOAT(maximumFrameRate, 60.0, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.maximumFrameRate", nil, [NSBundle mainBundle], @"Frame rate (FPS) when adaptive framerate is enabled and throughput is low but not 0.", @"Advanced setting: maximumFrameRate"));
DEFINE_FLOAT(lowPowerModeFrameRate, 30.0, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.lowPowerModeFrameRate", nil, [NSBundle mainBundle], @"Maximum frame rate (FPS) when low power mode is enabled.", @"Advanced setting: lowPowerModeFrameRate"));
DEFINE_BOOL(dwcLineCache, YES, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.dwcLineCache", nil, [NSBundle mainBundle], @"Enable cache of double-width character locations?\nThis should improve performance. It is always on in nightly builds. You must restart iTerm2 for this setting to take effect.", @"Advanced setting: dwcLineCache"));
DEFINE_BOOL(useGCDUpdateTimer, YES, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.useGCDUpdateTimer", nil, [NSBundle mainBundle], @"Use GCD-based update timer instead of NSTimer.\nThis should cause more regular screen updates. Restart iTerm2 after changing this setting.", @"Advanced setting: useGCDUpdateTimer"));
DEFINE_BOOL(drawOutlineAroundCursor, NO, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.drawOutlineAroundCursor", nil, [NSBundle mainBundle], @"Draw outline around underline and vertical bar cursors using background color.", @"Advanced setting: drawOutlineAroundCursor"));
DEFINE_BOOL(disableCustomBoxDrawing, NO, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.disableCustomBoxDrawing", nil, [NSBundle mainBundle], @"Use your typeface’s box-drawing characters instead of iTerm2’s custom drawing code.\nYou must restart iTerm2 after changing this setting.", @"Advanced setting: disableCustomBoxDrawing"));
DEFINE_INT(minimumWeightDifferenceForBoldFont, 4, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.minimumWeightDifferenceForBoldFont", nil, [NSBundle mainBundle], @"Minimum weight difference between regular and bold font.\nThis affects selection of the bold version of a font. Font weights go from 0 to 9. If no font can be found that has a high enough weight then the regular font will be double-struck with a small offset.", @"Advanced setting: minimumWeightDifferenceForBoldFont"));
DEFINE_FLOAT(underlineCursorHeight, 2, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.underlineCursorHeight", nil, [NSBundle mainBundle], @"Thickness of underline cursor.", @"Advanced setting: underlineCursorHeight"));
DEFINE_BOOL(preferSpeedToFullLigatureSupport, YES, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.preferSpeedToFullLigatureSupport", nil, [NSBundle mainBundle], @"Improves drawing performance at the expense of disallowing alphanumeric characters to belong to ligatures.", @"Advanced setting: preferSpeedToFullLigatureSupport"));
DEFINE_BOOL(enableContextualAlternates, YES, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.enableContextualAlternates", nil, [NSBundle mainBundle], @"Enable contextual alternates (calt) for ligature-capable fonts.\nWhen enabled, uses ligature level 2 which activates calt in addition to standard ligatures. Many coding fonts such as Monaspace, Iosevka, and Cascadia Code require this for their ligatures to work.", @"Advanced setting: enableContextualAlternates"));
DEFINE_BOOL(forceAntialiasingOnRetina, NO, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.forceAntialiasingOnRetina", nil, [NSBundle mainBundle], @"Force text to be anti-aliased on Retina displays.\nEnable this to use non-AA text on non-retina displays, which sometimes looks better.", @"Advanced setting: forceAntialiasingOnRetina"));
DEFINE_BOOL(makeSomePowerlineSymbolsWide, YES, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.makeSomePowerlineSymbolsWide", nil, [NSBundle mainBundle], @"Draw certain Powerline symbols double-width?\nThis matches how most “nerd” fonts render them, but your favorite one might not do this. An example code point that is affected is U+E0B8.", @"Advanced setting: makeSomePowerlineSymbolsWide"));

#if ENABLE_LOW_POWER_GPU_DETECTION
DEFINE_BOOL(useLowPowerGPUWhenUnplugged, NO, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.useLowPowerGPUWhenUnplugged", nil, [NSBundle mainBundle], @"Metal renderer uses integrated GPU when not connected to power?\nFor this to be effective you must disable “Disable Metal renderer when not connected to power”.", @"Advanced setting: useLowPowerGPUWhenUnplugged"));
