DEFINE_BOOL(underlineHyperlinks, YES, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.underlineHyperlinks", nil, [NSBundle mainBundle], @"Underline OSC 8 hyperlinks", @"Advanced setting: underlineHyperlinks"));
DEFINE_BOOL(solidUnderlines, NO, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.solidUnderlines", nil, [NSBundle mainBundle], @"Use solid underlines?\nWhen disabled, underlines break near text that would intersect them.", @"Advanced setting: solidUnderlines"));
DEFINE_BOOL(useMultiPassUnderlineRenderer, YES, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.useMultiPassUnderlineRenderer", nil, [NSBundle mainBundle], @"Use multi-pass underline renderer?\nFixes underline gaps with ligature fonts. Requires restart.", @"Advanced setting: useMultiPassUnderlineRenderer"));
DEFINE_SETTABLE_BOOL(showMetalFPSmeter, ShowMetalFPSmeter, NO, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.showMetalFPSmeter", nil, [NSBundle mainBundle], @"Show FPS meter\nRequires Metal renderer", @"Advanced setting: showMetalFPSmeter"));
DEFINE_BOOL(allowHDR, NO, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.allowHDR", nil, [NSBundle mainBundle], @"Allow HDR effects\nWhen enabled, iTerm2 may render some UI effects, such as the selected tab's outline, brighter than white on an HDR-capable display. Off by default because forcing the display into extended dynamic range can cause hangs on some systems.", @"Advanced setting: allowHDR"));
DEFINE_FLOAT(metalRedrawPeriod, 0.5, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.metalRedrawPeriod", nil, [NSBundle mainBundle], @"GPU renderer redraws at least this often, in seconds.\nThis is to work around a problem where the GPU renderer encounters a lot of latency when drawing for the first time after a short period of inactivity. Set this to a big number to render it ineffectual.", @"Advanced setting: metalRedrawPeriod"));
DEFINE_BOOL(animateGraphStatusBarComponents, YES, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.animateGraphStatusBarComponents", nil, [NSBundle mainBundle], @"Animate graph-based status bar components?\nTurn this off to reduce CPU/GPU usage in WindowServer.", @"Advanced setting: animateGraphStatusBarComponents"));
DEFINE_BOOL(disableTopRightIndicators, NO, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.disableTopRightIndicators", nil, [NSBundle mainBundle], @"Disable indicator icons that appear in the top right of a session?\nThis includes the following indicators: maximized pane, broadcast input, coprocess running, alert on next mark, output suppression, zoom, copy mode, and debug logging.", @"Advanced setting: disableTopRightIndicators"));
DEFINE_STRING(nativeRenderingCSSLight, @"", SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.nativeRenderingCSSLight", nil, [NSBundle mainBundle], @"Path to CSS file to customize native drawing (for light background colors).", @"Advanced setting: nativeRenderingCSSLight"));
DEFINE_STRING(nativeRenderingCSSDark, @"", SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.nativeRenderingCSSDark", nil, [NSBundle mainBundle], @"Path to CSS file to customize native drawing (for dark background colors).", @"Advanced setting: nativeRenderingCSSDark"));
DEFINE_BOOL(supportPowerlineExtendedSymbols, YES, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.supportPowerlineExtendedSymbols", nil, [NSBundle mainBundle], @"Include extended symbols when drawing Powerline natively.", @"Advanced setting: supportPowerlineExtendedSymbols"));
DEFINE_BOOL(alwaysUseLineStyleMarks, NO, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.alwaysUseLineStyleMarks", nil, [NSBundle mainBundle], @"Always use line-style marks?", @"Advanced setting: alwaysUseLineStyleMarks"));
DEFINE_FLOAT(alphaForDeselectedCommandShade, 0.25, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.alphaForDeselectedCommandShade", nil, [NSBundle mainBundle], @"Alpha value for shade that covers areas outside the currently selected command.", @"Advanced setting: alphaForDeselectedCommandShade"));
DEFINE_BOOL(showURLPreviewForSemanticHistory, YES, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.showURLPreviewForSemanticHistory", nil, [NSBundle mainBundle], @"Show URL preview on cmd-hover for semantic history matches.", @"Advanced setting: showURLPreviewForSemanticHistory"));
DEFINE_FLOAT(cursorAnimationMinDistance, 150.0, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.cursorAnimationMinDistance", nil, [NSBundle mainBundle], @"When animated cursor movement is enabled, only perform animation if the cursor moves at least this distance in points.", @"Advanced setting: cursorAnimationMinDistance"));
DEFINE_FLOAT(cursorSmearAnimationDuration, 0.1, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.cursorSmearAnimationDuration", nil, [NSBundle mainBundle], @"Duration in seconds for the “Animate large movements” cursor animation.", @"Advanced setting: cursorSmearAnimationDuration"));
DEFINE_FLOAT(cursorSlideAnimationDuration, 0.05, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.cursorSlideAnimationDuration", nil, [NSBundle mainBundle], @"Duration in seconds for smooth cursor slide animation.\nThis affects the \"Smooth slide\" cursor movement option.", @"Advanced setting: cursorSlideAnimationDuration"));
DEFINE_INT(cursorSlideAnimationMaxCells, 1, SECTION_DRAWING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.cursorSlideAnimationMaxCells", nil, [NSBundle mainBundle], @"Maximum horizontal distance in cells for smooth cursor slide animation.\nCursor movements larger than this will not animate.", @"Advanced setting: cursorSlideAnimationMaxCells"));

#pragma mark - Semantic History

#define SECTION_SEMANTIC_HISTORY @"Semantic History"

DEFINE_BOOL(ignoreHardNewlinesInURLs, NO, SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.ignoreHardNewlinesInURLs", nil, [NSBundle mainBundle], @"Ignore hard newlines for the purposes of locating URLs and file names for Semantic History.\nIf a hard newline occurs at the end of a line then ⌘-click will not see it all unless this setting is turned on. This is useful for some interactive applications. Turning this on will remove newlines from the \\3 and \\4 substitutions.", @"Advanced setting: ignoreHardNewlinesInURLs"));
// Note: square brackets are included for ipv6 addresses like http://[2600:3c03::f03c:91ff:fe96:6a7a]/
DEFINE_STRING(URLCharacterSet, @".?\\/:;$%=&_-,+~#@!*'(（)）|[]", SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.URLCharacterSet", nil, [NSBundle mainBundle], @"Non-alphanumeric characters considered part of a URL or file name for Semantic History.\nLetters and numbers are always considered part of the URL. These non-alphanumeric characters are used in addition for the purposes of figuring out where a URL begins and ends. You must restart iTerm2 for changes to this setting to take effect.", @"Advanced setting: URLCharacterSet"));
DEFINE_STRING(URLCharacterSetExclusions, @"¬", SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.URLCharacterSetExclusions", nil, [NSBundle mainBundle], @"Characters never considered part of a URL.\nThe characters in this string may never occur in a URL; when one is seen that delineates the beginning or end of a URL.", @"Advanced setting: URLCharacterSetExclusions"));
DEFINE_STRING(filenameCharacterSet, @"$@", SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.filenameCharacterSet", nil, [NSBundle mainBundle], @"Non-alphanumeric characters considered part of a filename. Note that URL characters (a separate advanced setting) are also allowed.\nLetters and numbers are always considered part of the URL. These non-alphanumeric characters are used in addition for the purposes of figuring out where a file begins and ends. You must restart iTerm2 for changes to this setting to take effect.", @"Advanced setting: filenameCharacterSet"));
DEFINE_INT(maxSemanticHistoryPrefixOrSuffix, 2000, SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.maxSemanticHistoryPrefixOrSuffix", nil, [NSBundle mainBundle], @"Maximum number of bytes of text before and after click location to take into account.\nThis also limits the size of the \\3 and \\4 substitutions.", @"Advanced setting: maxSemanticHistoryPrefixOrSuffix"));
DEFINE_STRING(pathsToIgnore, @"", SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.pathsToIgnore", nil, [NSBundle mainBundle], @"Paths to ignore for Semantic History.\nSeparate paths with a comma. Any file under one of these paths will not be openable with Semantic History. It is wise to add network file systems to this list, since they can be very slow.", @"Advanced setting: pathsToIgnore"));
DEFINE_BOOL(showYellowMarkForJobStoppedBySignal, YES, SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.showYellowMarkForJobStoppedBySignal", nil, [NSBundle mainBundle], @"Use a yellow for a Shell Integration prompt mark when the job is stopped by a signal.", @"Advanced setting: showYellowMarkForJobStoppedBySignal"));
DEFINE_BOOL(conservativeURLGuessing, NO, SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.conservativeURLGuessing", nil, [NSBundle mainBundle], @"URLs must contain a scheme?\nEnable this to reduce the number of false positives that semantic history thinks are a URL", @"Advanced setting: conservativeURLGuessing"));
DEFINE_BOOL(requireSlashInURLGuess, YES, SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.requireSlashInURLGuess", nil, [NSBundle mainBundle], @"Only consider a two+ part domain-name to be a URL if it also contains a slash.\nThis setting is used when guessing if a string is a URL for semantic history. When enabled, `example.com` would not be considered a URL but `example.com/` would be.", @"Advanced setting: requireSlashInURLGuess"))
DEFINE_STRING(trailingPunctuationMarks, @"!?…)].\"';:,", SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.trailingPunctuationMarks", nil, [NSBundle mainBundle], @"Characters to ignore at the end of a URL", @"Advanced setting: trailingPunctuationMarks"));
DEFINE_STRING(defaultURLScheme, @"https", SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.defaultURLScheme", nil, [NSBundle mainBundle], @"Default URL scheme.\nThis is applied to hostnames that are not a single word.", @"Advanced setting: defaultURLScheme"));
DEFINE_STRING(urlHandlerCommand, @"", SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.urlHandlerCommand", nil, [NSBundle mainBundle], @"Command to run when opening a clicked URL, instead of asking the OS to open it.\nWhen non-empty, this command runs as a silent background task via /bin/sh -c whenever you click a URL (including OSC 8 hyperlinks and auto-detected URLs) that iTerm2 would otherwise hand to the system. This is an interpolated string; use \\(url) for the URL and \\(background) for whether a background open was requested (1 if you held option while clicking, otherwise 0). The command is responsible for opening the URL however it likes (e.g., “open -g \\(url)” to open in the background). When empty, URLs open normally. iTerm2-internal schemes (iterm2:), URL schemes bound to a profile, and Semantic History file links are not affected.", @"Advanced setting: urlHandlerCommand"));
DEFINE_BOOL(restrictSemanticHistoryPrefixAndSuffixToLogicalWindow, YES, SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.restrictSemanticHistoryPrefixAndSuffixToLogicalWindow", nil, [NSBundle mainBundle], @"Respect soft boundaries for computing the prefix and suffix text passed to semantic history commands?\nDue to a long-standing bug this did not used to be respected. Soft boundaries were always respected for deciding what text was clicked on, but the prefix and suffix did not. If you have a semantic history command that depends on the bug, you can switch this off to get the pre-3.1.2 behavior.", @"Advanced setting: restrictSemanticHistoryPrefixAndSuffixToLogicalWindow"));
DEFINE_BOOL(enableSemanticHistoryOnNetworkMounts, NO, SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.enableSemanticHistoryOnNetworkMounts", nil, [NSBundle mainBundle], @"Enable semantic history for network-mounted filesystems?\nOnly enable this if you know your network-mounted filesystems are really fast and reliable. A slow filesystem may cause the entire iTerm2 app to hang.", @"Advanced setting: enableSemanticHistoryOnNetworkMounts"));
DEFINE_BOOL(prioritizeSmartSelectionActions, NO, SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.prioritizeSmartSelectionActions", nil, [NSBundle mainBundle], @"Check smart selection actions before existing files on cmd-click?", @"Advanced setting: prioritizeSmartSelectionActions"));
DEFINE_BOOL(disableSmartSelectionActionsOnClick, NO, SECTION_SEMANTIC_HISTORY, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.disableSmartSelectionActionsOnClick", nil, [NSBundle mainBundle], @"Disable performing the first matching Smart Selection’s Action on cmd-click?", @"Advanced setting: disableSmartSelectionActionsOnClick"));

#pragma mark - Debugging

#define SECTION_DEBUGGING @"Debugging"

DEFINE_BOOL(startDebugLoggingAutomatically, NO, SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.startDebugLoggingAutomatically", nil, [NSBundle mainBundle], @"Start debug logging automatically when iTerm2 is launched.", @"Advanced setting: startDebugLoggingAutomatically"));
DEFINE_BOOL(appendToExistingDebugLog, NO, SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.appendToExistingDebugLog", nil, [NSBundle mainBundle], @"Append to existing debug log rather than replacing it.", @"Advanced setting: appendToExistingDebugLog"));
DEFINE_BOOL(logDrawingPerformance, NO, SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.logDrawingPerformance", nil, [NSBundle mainBundle], @"Log stats about text drawing performance to console.\nUsed for performance testing.", @"Advanced setting: logDrawingPerformance"));
DEFINE_BOOL(showDirtyRectsInLegacyRenderer, NO, SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.showDirtyRectsInLegacyRenderer", nil, [NSBundle mainBundle], @"Outline dirty rects in the legacy renderer with random colors.\nUseful for visually verifying which regions of the text view are being repainted each frame. This affects only the legacy (non-GPU) renderer and does nothing when the GPU (Metal) renderer is active, so it is not a way to tell whether the GPU renderer is engaged. To use it, first turn off the GPU renderer in Settings → General → Magic.", @"Advanced setting: showDirtyRectsInLegacyRenderer"));
DEFINE_BOOL(logRestorableStateSize, NO, SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.logRestorableStateSize", nil, [NSBundle mainBundle], @"Log restorable state size info to /tmp/statesize.*.txt.", @"Advanced setting: logRestorableStateSize"));
DEFINE_BOOL(showBlockBoundaries, NO, SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.showBlockBoundaries", nil, [NSBundle mainBundle], @"Show line buffer block boundaries (issue 6207)", @"Advanced setting: showBlockBoundaries"));
DEFINE_BOOL(logToSyslog, NO, SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.logToSyslog", nil, [NSBundle mainBundle], @"Debug logs also write to the system log.", @"Advanced setting: logToSyslog"));
DEFINE_BOOL(logForegroundJobAncestryDiagnostics, NO, SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.logForegroundJobAncestryDiagnostics", nil, [NSBundle mainBundle], @"Log a detailed trace when a session’s foreground-job ancestor list unexpectedly shrinks.\nWhen an intermediate ancestor (such as the claude CLI) drops out of a tracked session’s foreground-job ancestry for a single process-cache update, log via RLog which pid held the vanished ancestor, whether it is still in the process table, and the full upward walk from the deepest foreground job. Used to diagnose spurious job-ended events that can tear down a Claude Code workgroup. Off by default; turn on only while reproducing an issue.", @"Advanced setting: logForegroundJobAncestryDiagnostics"));
DEFINE_STRING(fakeFullyQualifiedDomainName, @"", SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.fakeFullyQualifiedDomainName", nil, [NSBundle mainBundle], @"Override the local hostname used for localhost detection.\nWhen non-empty, the app behaves as though [NSHost fullyQualifiedDomainName] returns this value. Lets you test how localhost detection reacts to a hostname change without actually renaming your computer. Affects hosts reported after you change it; leave empty to use the real hostname.", @"Advanced setting: fakeFullyQualifiedDomainName"));
DEFINE_BOOL(aiChatVerboseConsoleLogging, NO, SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.aiChatVerboseConsoleLogging", nil, [NSBundle mainBundle], @"Log AI chat traffic to the system console.\nEmits per-turn user / agent / tool entries via NSLog so you can trace exactly what the agent received and produced. Useful for debugging tool dispatch and history translation. Off by default; turn on only while reproducing an issue.", @"Advanced setting: aiChatVerboseConsoleLogging"));
DEFINE_BOOL(aiChatRawWireLogging, NO, SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.aiChatRawWireLogging", nil, [NSBundle mainBundle], @"Log raw AI API requests and responses to disk.\nWrites every byte sent to and received from the AI vendor (full request headers, body, streaming chunks, final response, errors, and timing) to ~/Library/Application Support/iTerm2/AIChatWire/. One log file per app launch; rotate or delete it yourself when done. WARNING: the log captures Authorization / API-key headers and full prompt + response content verbatim. Off by default; turn on only while reproducing an issue and delete the files when finished.", @"Advanced setting: aiChatRawWireLogging"));
DEFINE_BOOL(logAITabTitleCorpus, NO, SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.logAITabTitleCorpus", nil, [NSBundle mainBundle], @"Log AI tab-title generations to a corpus file.\nWhen the AI tab-title component runs the on-device model, append the inputs (foreground job, command line, directory, host, and visible screen), the system prompt used, the model, the generated title, and timing as one JSON line to ~/Library/Application Support/iTerm2/AITabTitleCorpus/corpus.jsonl. Builds a replayable corpus for grading prompts and models offline (see the corpus grader in the AI live harness). WARNING: captures full screen contents verbatim. Off by default; turn on only while collecting data and delete the file when finished.", @"Advanced setting: logAITabTitleCorpus"));
#if DEBUG
// Localization unneeded
DEFINE_STRING(alternateSSHIntegrationScript, @"", SECTION_DEBUGGING, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.alternateSSHIntegrationScript", nil, [NSBundle mainBundle], @"Alternate SSH integration python script", @"Advanced setting: alternateSSHIntegrationScript"));
#endif

#pragma mark - Session

#define SECTION_SESSION @"Session"

DEFINE_BOOL(runJobsInServers, YES, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.runJobsInServers", nil, [NSBundle mainBundle], @"Enable session restoration.\nSession restoration runs jobs in separate processes. They will survive crashes, force quits, and upgrades.\nYou must restart iTerm2 for this change to take effect.", @"Advanced setting: runJobsInServers"));
DEFINE_BOOL(bootstrapDaemon, YES, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.bootstrapDaemon", nil, [NSBundle mainBundle], @"Allow sessions to survive logging out and back in.\nThis breaks the “auth sufficient pam_tid.so” hack some people use to allow sudo to authenticate with Touch ID.", @"Advanced setting: bootstrapDaemon"));

DEFINE_BOOL(killJobsInServersOnQuit, YES, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.killJobsInServersOnQuit", nil, [NSBundle mainBundle], @"User-initiated Quit (⌘Q) of iTerm2 will kill all running jobs.\nApplies only when session restoration is on.", @"Advanced setting: killJobsInServersOnQuit"));
DEFINE_SETTABLE_BOOL(suppressRestartAnnouncement, SuppressRestartAnnouncement, NO, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.suppressRestartAnnouncement", nil, [NSBundle mainBundle], @"Suppress the Restart Session offer.\nWhen a session terminates, it will offer to restart itself. Turn this on to suppress the offer permanently.", @"Advanced setting: suppressRestartAnnouncement"));
DEFINE_BOOL(showSessionRestoredBanner, YES, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.showSessionRestoredBanner", nil, [NSBundle mainBundle], @"When restoring a session without restoring a running job, draw a banner saying “Session Contents Restored” below the restored contents.", @"Advanced setting: showSessionRestoredBanner"));
DEFINE_DEPRECATED_STRING(autoLogFormat,
                         @"\\(creationTimeString).\\(profileName).\\(termid).\\(iterm2.pid).\\(autoLogId).log", SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.autoLogFormat", nil, [NSBundle mainBundle], @"Format for automatic session log filenames.\nSee the Badges documentation for supported substitutions.", @"Advanced setting: autoLogFormat"));
DEFINE_BOOL(autologAppends, YES, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.autologAppends", nil, [NSBundle mainBundle], @"Automatic session logging appends to existing files.\nWhen set to No, the file will be overwritten instead.", @"Advanced setting: autologAppends"));
DEFINE_STRING(logTimestampFormat, @"yyyy-MM-dd hh.mm.ss.SSS", SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.logTimestampFormat", nil, [NSBundle mainBundle], @"Format for log timestamps. See Unicode TR 35-31 for syntax.\nYou must restart iTerm2 for changes to this setting to take effect.", @"Advanced setting: logTimestampFormat"));
DEFINE_BOOL(focusNewSplitPaneWithFocusFollowsMouse, YES, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.focusNewSplitPaneWithFocusFollowsMouse", nil, [NSBundle mainBundle], @"When focus follows mouse is enabled, should new split panes automatically be focused?", @"Advanced setting: focusNewSplitPaneWithFocusFollowsMouse"));
DEFINE_BOOL(NoSyncSuppressRestartSessionConfirmationAlert, NO, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.NoSyncSuppressRestartSessionConfirmationAlert", nil, [NSBundle mainBundle], @"Suppress restart session confirmation alert.\nDon't ask for a confirmation when manually restarting a session.", @"Advanced setting: NoSyncSuppressRestartSessionConfirmationAlert"));
DEFINE_BOOL(showAutomaticProfileSwitchingBanner, YES, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.showAutomaticProfileSwitchingBanner", nil, [NSBundle mainBundle], @"Show a “Switched to profile” message when Automatic Profile Switching activates.", @"Advanced setting: showAutomaticProfileSwitchingBanner"));
DEFINE_BOOL(preserveFontSizeOnAutomaticProfileSwitch, YES, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.preserveFontSizeOnAutomaticProfileSwitch", nil, [NSBundle mainBundle], @"Preserve font zoom level when Automatic Profile Switching changes profiles.", @"Advanced setting: preserveFontSizeOnAutomaticProfileSwitch"));
DEFINE_BOOL(autoLockSessionNameOnEdit, YES, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.autoLockSessionNameOnEdit", nil, [NSBundle mainBundle], @"Auto-lock session name after editing it.", @"Advanced setting: autoLockSessionNameOnEdit"));
DEFINE_BOOL(aiGeneratedTabTitles, NO, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.aiGeneratedTabTitles", nil, [NSBundle mainBundle], @"Name tabs after the work on screen, using on-device AI?\nWhen enabled, the session variable “aiTitle” holds a short name for the task visible in the session, which you can show by adding the “AI-generated name” title component or using \\(session.aiTitle) in a custom title format. Requires Apple Intelligence; the screen contents never leave this Mac, and no API key is used.", @"Advanced setting: aiGeneratedTabTitles"));
DEFINE_FLOAT(timeoutForDaemonAttachment, 10, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.timeoutForDaemonAttachment", nil, [NSBundle mainBundle], @"How long to wait when trying to attach to an iTerm daemon at startup when restoring windows (in seconds)?", @"Advanced setting: timeoutForDaemonAttachment"));
DEFINE_BOOL(logTimestampsWithPlainText, YES, SECTION_SESSION, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.logTimestampsWithPlainText", nil, [NSBundle mainBundle], @"When logging plain text, include timestamps for each line?", @"Advanced setting: logTimestampsWithPlainText"));
