DEFINE_INT(companionStreamMaxLeadMilliseconds, 500, SECTION_EXPERIMENTAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.companionStreamMaxLeadMilliseconds", nil, [NSBundle mainBundle], @"iTerm2 Buddy live stream: maximum capture-time lead, in milliseconds.\nThe host stops sending new frames once it is more than this far ahead of the last frame the phone acknowledged, then resumes when the phone catches up. Larger values tolerate more link latency at the cost of a live view that can lag further behind. Only the frame rate is affected; per-frame quality is unchanged.", @"Advanced setting: companionStreamMaxLeadMilliseconds"));
DEFINE_INT(companionStreamMaxQueueDepth, 4, SECTION_EXPERIMENTAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.companionStreamMaxQueueDepth", nil, [NSBundle mainBundle], @"iTerm2 Buddy live stream: maximum phone decode-queue depth.\nThe host stops sending new frames once the phone reports more than this many frames queued for decode/display, then resumes as the queue drains. Larger values let more frames pile up on the phone before backing off. Only the frame rate is affected; per-frame quality is unchanged.", @"Advanced setting: companionStreamMaxQueueDepth"));
DEFINE_FLOAT(companionStreamBitrateMultiplier, 1.0, SECTION_EXPERIMENTAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.companionStreamBitrateMultiplier", nil, [NSBundle mainBundle], @"iTerm2 Buddy live stream: video bitrate multiplier.\nScales the resolution-derived encoder bitrate. Values above 1 make streamed text sharper at the cost of bandwidth; values below 1 save bandwidth at the cost of sharpness. The result is still clamped to the stream’s minimum and ceiling bitrates.", @"Advanced setting: companionStreamBitrateMultiplier"));
DEFINE_FLOAT(companionWakeupCoalesceInterval, 5.0, SECTION_EXPERIMENTAL, NSLocalizedStringWithDefaultValue(@"AdvancedSetting.companionWakeupCoalesceInterval", nil, [NSBundle mainBundle], @"iTerm2 Buddy push notifications: minimum seconds between wakeup pushes.\nA wakeup push tells the paired phone to fetch every new message and alert at once, so several in quick succession are wasteful and can leave a later one with nothing to show (the generic “Your agent has an update.” placeholder). The host sends the first wakeup immediately, then coalesces any that follow within this interval into a single trailing wakeup. Lower values notify sooner but coalesce less; higher values coalesce bursts more aggressively.", @"Advanced setting: companionWakeupCoalesceInterval"));

